add_action( 'woocommerce_add_to_cart', 'perfectpixel_auto_coupon_sync', 20 );
add_action( 'woocommerce_cart_item_removed', 'perfectpixel_auto_coupon_sync', 20 );

function perfectpixel_auto_coupon_cart_qualifies() {
	$ids = wp_parse_id_list( '{{auto_coupon_product_ids}}' );
	foreach ( WC()->cart->get_cart() as $item ) {
		if ( ! $ids || in_array( (int) $item['product_id'], $ids, true ) || in_array( (int) $item['variation_id'], $ids, true ) ) {
			return true;
		}
	}
	return false;
}

function perfectpixel_auto_coupon_sync() {
	static $running = false;
	$code = wc_format_coupon_code( '{{auto_coupon_code}}' );
	if ( $running || '' === $code || ! WC()->cart ) {
		return;
	}
	$running    = true;
	$has_coupon = WC()->cart->has_discount( $code );
	$qualifies  = perfectpixel_auto_coupon_cart_qualifies();

	if ( $qualifies && ! $has_coupon ) {
		WC()->cart->apply_coupon( $code );
	} elseif ( ! $qualifies && $has_coupon ) {
		WC()->cart->remove_coupon( $code );
		WC()->cart->calculate_totals();
	}
	$running = false;
}
